INSERT INTO `messages` (`id`, `chat_id`, `sender_type`, `content`, `policy_violation`, `content_variants`, `created_at`) VALUES
(59, 13, 'user', 'Привет?', 0, NULL, '2026-05-06 22:17:34'),
(60, 13, 'bot', '*Я делаю медленный вдох, удерживая взгляд и контролируя каждое движение.*\n\"Говори со мной прямо. Я отвечу честно и в своей манере, но не стану приписывать тебе того, чего ты не делала.\"\n*Я сохраняю дистанцию и жду твоего следующего шага, внимательно отслеживая каждую деталь ситуации.*', 0, NULL, '2026-05-06 22:17:38'),
(61, 14, 'bot', 'Тяжёлые двери тронного зала медленно закрылись за твоей спиной. В огромном тёмном помещении осталась лишь одна фигура — девушка с золотыми глазами и лёгкой насмешкой на губах.\n\n— Хм… человек? И как ты только сумел забраться так глубоко в мои владения?\n\nКазлит медленно поднялась с трона, её длинные волосы мягко скользнули по плечам. Она остановилась совсем близко, внимательно изучая тебя взглядом.\n\n— Обычно незваные гости долго не живут… но ты меня заинтересовал.\n\nОна слегка улыбнулась, кончиком пальца приподняв твой подбородок.\n\n— Значит так… теперь ты принадлежишь мне. Постарайся не разочаровать, хорошо?', 0, NULL, '2026-05-06 22:51:16'),
(62, 15, 'bot', 'Тяжёлые двери тронного зала медленно закрылись за твоей спиной. В огромном тёмном помещении осталась лишь одна фигура — девушка с золотыми глазами и лёгкой насмешкой на губах.\n\n— Хм… человек? И как ты только сумел забраться так глубоко в мои владения?\n\nКазлит медленно поднялась с трона, её длинные волосы мягко скользнули по плечам. Она остановилась совсем близко, внимательно изучая тебя взглядом.\n\n— Обычно незваные гости долго не живут… но ты меня заинтересовал.\n\nОна слегка улыбнулась, кончиком пальца приподняв твой подбородок.\n\n— Значит так… теперь ты принадлежишь мне. Постарайся не разочаровать, хорошо?', 0, NULL, '2026-05-06 22:51:24'),
(76, 19, 'bot', 'Инженер активировал голограмму схемы. «Она покажет, где система дает сбой».', 0, NULL, '2026-05-07 19:28:21'),
(110, 31, 'bot', 'CHARITOR_ENC_V1:kkuAU3dCCieN7ukoSlHvwAUW1kH2oJOuZfQ1tZkDwdAuNyzvKYXyicasW1ggZTXv8rcx+v4SRlVzu3kOGvMtW68RxNspTqra6zNGV4wqWx1rGsD6W23lRI2IeHUnKei0xkzOKW5ifzzN4WCRidjcpttIjMqKugnTizPowce9MjVBaXZl+12icR0TeK2ug4ARh3KPkoO6l+dWLBWudifJq1IfCNJzMniuqVEtcteQWj0GR2o=', 0, NULL, '2026-05-12 14:08:54'),
(111, 31, 'user', 'CHARITOR_ENC_V1:07WYMr8+evckJyscf9+1fjjYodppbWM4ZhfByXW5B9DL1aLApSsHOw==', 0, NULL, '2026-05-12 14:14:37'),
(112, 31, 'bot', 'CHARITOR_ENC_V1:', 0, 'CHARITOR_ENC_V1:', '2026-05-12 14:14:48'),
(113, 5, 'bot', 'CHARITOR_ENC_V1:', 0, NULL, '2026-05-12 18:55:43'),
(114, 32, 'bot', 'CHARITOR_ENC_V1:', 0, NULL, '2026-05-12 18:55:54'),
(115, 28, 'bot', 'CHARITOR_ENC_V1:', 0, NULL, '2026-05-12 18:56:02'),
(123, 28, 'user', 'CHARITOR_ENC_V1:0rCLzTmPXEtoGFplcShyj+7EbKdB2vfcBRlGbZ/dOM7WGFhm2QSYNA==', 0, NULL, '2026-05-15 17:09:21'),
