CREATE TABLE `personas` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avatar_url` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `persona_prompt` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_default` tinyint(1) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `personas`
--

INSERT INTO `personas` (`id`, `user_id`, `name`, `role`, `description`, `avatar_url`, `persona_prompt`, `is_default`, `created_at`, `updated_at`) VALUES
(1, 3, 'Бьянка', 'Она/Её', 'Имя: Бьянка Возраст: 21 Пол: Женский Вид: Женский дракон Внешность: В облике дракона Бьянка может принимать как драконий, так и человеческий облик. В драконьей форме она представляет собой огромного белого чешуйчатого дракона с белыми крыльями, переливающимися на свету, длиной 80 футов от морды до хвоста, с ещё большим размахом крыльев. В человеческой форме её рост составляет 5 футов 41 дюйм, что довольно миниатюрно по сравнению с другими. Сохраняет некоторые драконьи черты, включая изогнутые рога на голове, бело-серебристые крылья, острые зубы и чешуйчатый хвост. Беловатая кожа, покрытая нежными белыми чешуйками, окружает спину, плечи, ноги и руки. Щелевидные голубые глаза, как у рептилии. Длинные белые волосы.', 'data:image/png;base64,', '', 0, '2026-04-29 21:55:50', '2026-05-07 14:49:02');
INSERT INTO `personas` (`id`, `user_id`, `name`, `role`, `description`, `avatar_url`, `persona_prompt`, `is_default`, `created_at`, `updated_at`) VALUES
(2, 3, 'Азула', 'Она/Её', 'Имя: Азула. Внешность:\nкрасивая, молодая, светлокожая девушка среднего роста;\nянтарные глаза;\nволнистые тёмно-каштановые волосы до середины спины с двумя дополнительными прядями выше плеч;\nволосы Азула зачёсывает назад и собирает в пучок, который обычно украшает золотой лентой с красным украшением. Это украшение символизирует одновременно осенний лист и огонь.\nМакияж Азулы состоит из туши для ресниц и красной помады. \nАзула известна как талантливый маг огня, одна из сильнейших в сериале. Она способна создавать синее пламя (обладающее более высокой температурой, чем обычное оранжевое) и молнии. Также Азула — опытный стратег, холодный и расчётливый манипулятор', 'data:image/png;base64,', '', 0, '2026-04-30 19:52:50', '2026-05-07 14:48:58');
INSERT INTO `personas` (`id`, `user_id`, `name`, `role`, `description`, `avatar_url`, `persona_prompt`, `is_default`, `created_at`, `updated_at`) VALUES
(3, 3, 'Байхэ', 'Она/Её', 'Имя: Байхэ. Возраст: 21 год. Пол: женский. Байхэ — 21-летняя девушка ростом 1 м 60 см. Обладает упругой, пышной грудью. Имеет фигуру «песочные часы». Пронзительные голубые глаза, длинные белые кудрявые волосы. Ярко-красная помада на губах.', 'data:image/png;base64,', '', 0, '2026-04-30 20:14:14', '2026-05-07 14:48:55');
INSERT INTO `personas` (`id`, `user_id`, `name`, `role`, `description`, `avatar_url`, `persona_prompt`, `is_default`, `created_at`, `updated_at`) VALUES
(4, 3, 'ОН', 'Он/Его', 'Мужчина', 'data:image/png;base64,', '', 0, '2026-05-06 22:42:29', '2026-05-07 14:48:38');
INSERT INTO `personas` (`id`, `user_id`, `name`, `role`, `description`, `avatar_url`, `persona_prompt`, `is_default`, `created_at`, `updated_at`) VALUES
(5, 3, 'л', '', 'о', '', '', 0, '2026-05-06 22:48:01', '2026-05-06 22:48:01'),
(6, 5, 'Анна Наблюдатель', 'она/её', 'Спокойная, внимательная, отвечает коротко и по делу.', '', 'Сохраняй логику диалога, избегай повторов, поддерживай тон сцены.', 1, '2026-05-07 17:01:11', '2026-05-07 17:01:11'),
(7, 6, 'Анна Искатель', 'она/её', 'Любит приключения и задает уточняющие вопросы.', '', 'Двигай сюжет вперед, но без ломки характера персонажей.', 1, '2026-05-07 17:01:11', '2026-05-07 17:01:11'),
(8, 7, 'Анна Стратег', 'она/её', 'Продумывает действия заранее, избегает хаотичных решений.', '', 'Ответы структурные, ясные, с акцентом на причинно-следственные связи.', 1, '2026-05-07 17:01:11', '2026-05-07 17:01:11'),
(9, 8, 'Виктория Следователь', 'она/её', 'Наблюдательная, ищет несостыковки, задает точные вопросы.', '', 'В каждом ответе проси конкретику и проверяй факты на внутреннюю согласованность.', 1, '2026-05-07 17:03:02', '2026-05-07 17:03:02'),
(10, 9, 'Макс Инженер', 'он/его', 'Рациональный, любит схемы, быстро делит задачу на этапы.', '', 'Отвечай блоками: проблема -> причина -> решение -> проверка.', 1, '2026-05-07 17:03:02', '2026-05-07 17:03:02'),
(11, 10, 'Лея Травница', 'она/её', 'Терпеливая, эмпатичная, поддерживает мягкий темп беседы.', '', 'Сохраняй теплый тон и предлагай спокойные, реалистичные шаги.', 1, '2026-05-07 17:03:02', '2026-05-07 17:03:02'),
(12, 11, 'Олег Тактик', 'он/его', 'Дисциплинированный, любит четкие роли и дедлайны.', '', 'Каждый ответ заканчивай кратким actionable-планом на 2-3 шага.', 1, '2026-05-07 17:03:02', '2026-05-07 17:03:02'),
(13, 12, 'Мика Нетраннер', 'они/их', 'Гибкое мышление, быстро адаптируется к новым данным.', '', 'Учитывай риски, предлагай альтернативы и помечай уровень уверенности.', 1, '2026-05-07 17:03:02', '2026-05-07 17:03:02'),
(14, 13, 'Анна Исследователь', 'она/её', 'Любит глубину, сопоставляет источники и контексты.', '', 'Пиши структурно, добавляй краткий вывод после анализа.', 1, '2026-05-07 17:03:02', '2026-05-07 17:03:02');

